// InjectionToken for a config object
const API_CONFIG = new InjectionToken<{ baseUrl: string; timeout: number }>('api.config');

// Provide in the module/app config
bootstrapApplication(AppComponent, {
  providers: [
    { provide: API_CONFIG, useValue: { baseUrl: '/api/v2', timeout: 5000 } }
  ]
});

// Inject in a service
@Injectable({ providedIn: 'root' })
export class ApiService {
  private config = inject(API_CONFIG);
  get baseUrl() { return this.config.baseUrl; }
}

// useFactory: inject with dependencies
{ provide: LogService,
  useFactory: (env: EnvironmentService) =>
    env.isProd() ? new SilentLogger() : new ConsoleLogger(),
  deps: [EnvironmentService] }

// Multi-providers: register multiple HTTP interceptors
{ provide: HTTP_INTERCEPTORS, useClass: AuthInterceptor, multi: true },
{ provide: HTTP_INTERCEPTORS, useClass: LoggingInterceptor, multi: true }

// Component-level provider: each instance gets its own StateService
@Component({
  providers: [StateService]  // NOT a singleton — new instance per component
})
export class WidgetComponent {
  private state = inject(StateService);
}

// @Optional: inject a service that may not be provided
@Directive({ selector: '[tooltip]' })
export class TooltipDirective {
  private tooltipConfig = inject(TOOLTIP_CONFIG, { optional: true });
  // tooltipConfig is null if TOOLTIP_CONFIG was not provided
}

// @SkipSelf: useful in directives to get parent's instance
constructor(@SkipSelf() private parentService: ParentService) {}
